import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

/**
 * Global registry letting the surface a chat is embedded next to suggest the welcome headline
 * (e.g. the email template editor registering a template-flavored prompt). Providers register on
 * mount and deregister on unmount; the most recent registration wins, and with none the welcome
 * falls back to its default rotation.
 */

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface welcomeHeadlineLogicValues {
    headlineByProvider: Record<string, string>
    overrideHeadline: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface welcomeHeadlineLogicActions {
    deregisterHeadline: (providerId: string) => {
        providerId: string
    }
    registerHeadline: (
        providerId: string,
        headline: string
    ) => {
        headline: string
        providerId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface welcomeHeadlineLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        overrideHeadline: (headlineByProvider: Record<string, string>) => string | null
    }
}

export type welcomeHeadlineLogicType = MakeLogicType<
    welcomeHeadlineLogicValues,
    welcomeHeadlineLogicActions,
    Record<string, any>,
    welcomeHeadlineLogicMeta
>

export const welcomeHeadlineLogic = kea<welcomeHeadlineLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'welcomeHeadlineLogic']),
    actions({
        registerHeadline: (providerId: string, headline: string) => ({ providerId, headline }),
        deregisterHeadline: (providerId: string) => ({ providerId }),
    }),
    reducers({
        headlineByProvider: [
            {} as Record<string, string>,
            {
                registerHeadline: (state, { providerId, headline }) => ({ ...state, [providerId]: headline }),
                deregisterHeadline: (state, { providerId }) => {
                    const { [providerId]: _, ...rest } = state
                    return rest
                },
            },
        ],
    }),
    selectors({
        overrideHeadline: [
            (s) => [s.headlineByProvider],
            (headlineByProvider: Record<string, string>): string | null => {
                const headlines = Object.values(headlineByProvider)
                return headlines.length > 0 ? headlines[headlines.length - 1] : null
            },
        ],
    }),
])
